    7'd77: rom_row = 256'hfff91611f131fceacc243c3aaa1acdf4ec42bce4e4e1f001d7f5e554ce48ef19;
    7'd78: rom_row = 256'he554ff8113ea0f1ec201b8f718d49981bc05d726a60bf4f316893a071a7ffc43;
    7'd79: rom_row = 256'h0dd41e20214ce001d6e80a3c0c35cce41543e1522c2cf726e7ec1617f32cf50f;
    7'd80: rom_row = 256'h4deecf490decb8e0e20e222602504a59dc19150306ef08f4c6440f01f2d8e31a;
    7'd81: rom_row = 256'h0803fa2dfcf08bd37fef7049de655c03dcd219193e5b4d59d2ed810b7f1d6512;
    7'd82: rom_row = 256'h817f7f8110fe7fc73881ba81e58181817f817f7f815d7f7f2d8181d37f7f81f4;
    7'd83: rom_row = 256'hfe3fece60370310fe817ea0c2fc6b24523301b0c37540c20ced4e8f9f0133a02;
    7'd84: rom_row = 256'ha5f20fee4f46e3da8141253d3b108198fbb4921ab38eab8128b4e181814f2a17;
    7'd85: rom_row = 256'h29d911af517febcddff892cdbecb0207181dc5293c0a81b801f2f4e2e3177f03;
    7'd86: rom_row = 256'ha7162924fe5ee8c1eadb5323e0f50b1ee41dd2ef3b3202d97fe3812f19376713;
    7'd87: rom_row = 256'h21220826f529f1d840bd431cbae0e815fb09dc0e0d544d65b030234775243614;
    7'd88: rom_row = 256'he12224392c44db9ef11817ca923a7eb003dc2a382a1b15fffba110b8d63d160e;
    7'd89: rom_row = 256'hd840fad8a46e1a112b0a3db80c81b7ddf6bbfaf0cfa14d691381b82e172ea311;
    7'd90: rom_row = 256'h2cf32ff62fce11e83abde2a522beedd7ccfc811bcfd513f038dd1bce0ad23322;
    7'd91: rom_row = 256'h192d1548c581bc853ad95e7fc106214009812e2a03817f2b0c05270051ef81ed;
    7'd92: rom_row = 256'h1c343ba5c8c82eb8b9c581e6f281ee815181fd61449a84817c9e9cf3a67feeec;
    7'd93: rom_row = 256'hb9ad7f8c81ea4d2053a20634e9f9d80f81818181cf81523b7f24df237f8181ec;
    7'd94: rom_row = 256'h2dc21436e15816c90fe9200bf419ed0956f4bce400bb1e00e7fbe8ec2de9e672;
    7'd95: rom_row = 256'hded1e6b035ebba2705efeedf071d072cd2dbdb02e2fc2023dd440addedcf16fe;
    7'd96: rom_row = 256'hba810bab818e3bfda81ea0a5e2b5b1d61c818181c98a99b329eaeaa9b281b781;
